window.kbPageData["views/entry/k-e77baa686aac3625"] = {"key":"entry/k-e77baa686aac3625","state":{"route":"entry/k-e77baa686aac3625"},"node":{"id":"k-e77baa686aac3625","mode":"k","title":"消费者公平交易权","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["销售时未显著告知开机广告可侵害消费者公平交易权"],"qs":["江苏 2023 B类 行测#15"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"消费者购买商品或接受服务时，有权获得质量有保障、价格合理、计量正确等公平交易条件，并有权拒绝经营者的强制交易行为。","review":{"definition":"消费者购买商品或接受服务时，有权获得质量有保障、价格合理、计量正确等公平交易条件，并有权拒绝经营者的强制交易行为。","explanation":"公司销售电视时未显著告知开机必播15秒广告，消费者在作出购买决定前缺少一项会影响日常使用的信息。本题解析以这一销售行为违反诚信原则为由，认定B项关于公平交易权受侵害的说法成立。A项关注的是使用电视时能否自主选择接受广告。","references":[],"evidence":"未在销售时以显著的方式提示或告知消费者","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2023 B类 行测#15":{"paper":"江苏 2023 B类 行测","n":15,"mod":"常识判断","src":["22262c34d18cd68fbee4.pdf",3],"asrc":["b08f2713d73015eac675.pdf",6],"card":"66101090aa309c4eebdfef44","links":[{"id":"k-e77baa686aac3625","role":"解题依据","why":"销售时对开机广告的告知情况是判断交易是否公平的依据。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-e77baa686aac3625":[["江苏 2023 B类 行测#15"]]}};
